DO $$
BEGIN
  UPDATE visits
  SET status = 'pending_rebooking'
  WHERE follow_up_needed = TRUE
    AND follow_up_scheduled = FALSE
    AND status = 'completed';

  UPDATE visits
  SET rebooking_incentive = visit_fee * 0.20
  WHERE status = 'pending_rebooking';

  UPDATE visits
  SET eligible_for_testimonial = TRUE
  WHERE minutes_duration >= 30
    AND patient_satisfaction_score >= 4;
END $$;

SELECT * FROM visits ORDER BY visit_id;

DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_tier INT;
  cur_billing DATE;
BEGIN
  FOR rec IN SELECT * FROM renewal_events ORDER BY event_id LOOP
    SELECT status, plan_tier, next_billing_date INTO cur_status, cur_tier, cur_billing FROM subscriptions WHERE subscription_id = rec.subscription_id;
    IF rec.event_type = 1 AND cur_status = 'active' THEN
      UPDATE subscriptions SET next_billing_date = next_billing_date + (rec.billing_date_offset_days || ' days')::INTERVAL, plan_tier = rec.new_tier WHERE subscription_id = rec.subscription_id;
    ELSIF rec.event_type = 2 AND cur_status = 'active' THEN
      UPDATE subscriptions SET status = 'cancelled', next_billing_date = NULL WHERE subscription_id = rec.subscription_id;
    ELSIF rec.event_type = 3 AND cur_status = 'cancelled' THEN
      UPDATE subscriptions SET status = 'active', next_billing_date = CURRENT_DATE + INTERVAL '30 days' WHERE subscription_id = rec.subscription_id;
    END IF;
  END LOOP;
END $$;
SELECT * FROM subscriptions ORDER BY subscription_id;

CREATE OR REPLACE FUNCTION get_invites_by_status(p_status VARCHAR(20))
RETURNS TABLE (
  sender_username VARCHAR(50),
  receiver_username VARCHAR(50),
  invite_status VARCHAR(20),
  sent_at TIMESTAMP
)
AS $$
BEGIN
  RETURN QUERY (
    SELECT si.sender_username, si.receiver_username, si.invite_status, si.sent_at
    FROM squad_invites si
    WHERE si.invite_status = p_status
    ORDER BY si.sent_at DESC
  );
END;
$$ LANGUAGE plpgsql;

SELECT * FROM get_invites_by_status('accepted');
